use super::*;

/// Returns true if the prompt_id was generated by the shell for a
/// server-initiated auto-wake turn (background task or subagent completion).
pub(crate) fn is_server_initiated_prompt(prompt_id: &str) -> bool {
    xai_grok_shell::session::PromptOrigin::from_prompt_id(prompt_id).is_synthetic()
}

/// Returns true if the prompt_id is a scheduled-task (`/loop`) fire.
///
/// Cron turns are synthetic (so [`is_server_initiated_prompt`] is also true for
/// them), but UNLIKE auto-wake / subagent-completion turns they are
/// CLIENT-driven via `MvpAgent::prompt()` and therefore DO emit a matching
/// `x.ai/session/prompt_complete` turn-end signal. A viewer can thus safely
/// enter `TurnRunning` for them (the exit exists, so it won't strand) — which is
/// what lets the dashboard show a running `/loop` session as Working.
pub(crate) fn is_scheduler_fired_prompt(prompt_id: &str) -> bool {
    matches!(
        xai_grok_shell::session::PromptOrigin::from_prompt_id(prompt_id),
        xai_grok_shell::session::PromptOrigin::SchedulerFired
    )
}

/// Returns true for the auto-wake turn families (`task-completed-…`,
/// `subagent-completed-…`, `workflow-completed-…`, `notifications-…`). These run non-adopted — no
/// `PromptResponse`, no viewer finalize — so their durable `TurnCompleted` is
/// the only signal marking the back-to-idle point (see [`finish_wake_turn`];
/// a chatty wake closes with a marker, a silent one stays markerless).
/// Deliberately narrower than "non-adopted
/// synthetic": goal turns render through the goal chip/loop chrome and
/// `plan-resume-…` keeps its own markerless shape.
pub(crate) fn is_wake_prompt(prompt_id: &str) -> bool {
    matches!(
        xai_grok_shell::session::PromptOrigin::from_prompt_id(prompt_id),
        xai_grok_shell::session::PromptOrigin::TaskCompleted { .. }
            | xai_grok_shell::session::PromptOrigin::SubagentCompleted { .. }
            | xai_grok_shell::session::PromptOrigin::WorkflowCompleted { .. }
            | xai_grok_shell::session::PromptOrigin::NotificationDrain
    )
}

/// Whether a running `prompt_id` is adoptable — i.e. safe to bind as the
/// viewer's `current_prompt_id` and show as a live `TurnRunning`. The invariant:
/// adoptable iff the turn emits a terminal `x.ai/session/prompt_complete`, the
/// only non-interactive way a viewer leaves `TurnRunning`. That holds for
/// user-driven turns and `/loop` (`scheduler-fired-…`) fires — both run via
/// `MvpAgent::prompt()` — and is false for actor-run synthetic turns
/// (task-completed / subagent-completion / notification-drain / goal-*), which
/// have no such exit, so adopting one strands the viewer in `TurnRunning`.
///
/// This is the pure pid-only synthetic-turn guard. It serves the live-delta
/// viewer gate and the `queue/changed` turn-start shim (the latter negated, as a
/// skip) directly. The two adoption-on-load paths (`SessionLoaded` in
/// `dispatch.rs`, the reconnect-reload `finalize_reload_and_maybe_adopt`) instead
/// call the agent-aware [`AgentView::should_adopt_running_prompt`], which ANDs
/// this guard with "not terminal-in-replay" so an already-ended turn replayed on
/// reattach is not re-adopted.
///
/// [`AgentView::should_adopt_running_prompt`]: crate::app::agent_view::AgentView::should_adopt_running_prompt
pub(crate) fn should_adopt_running_prompt(prompt_id: &str) -> bool {
    !is_server_initiated_prompt(prompt_id) || is_scheduler_fired_prompt(prompt_id)
}

/// Compute the monotonic anchor a VIEWER should use as its turn-start time.
///
/// A viewer adopts the driver's turn mid-stream, so stamping `Instant::now()`
/// would make its elapsed counter — and the final "Worked for X" marker
/// (both read off `turn_started_at` via [`AgentView::turn_elapsed`]) — read
/// LESS than the driver's by the time-to-first-delta. The shell records the
/// authoritative wall-clock turn start in `meta.turnStartMs` (UTC ms, stamped
/// at the top of the turn), so back-date the anchor from it; the viewer's
/// elapsed then matches the driver's, both live and on completion. Falls back
/// to `now` when `turnStartMs` is absent (older shell) or the wall clock is
/// skewed forward.
pub(super) fn viewer_turn_anchor(turn_start_ms: Option<i64>) -> std::time::Instant {
    let now = std::time::Instant::now();
    let Some(start_ms) = turn_start_ms else {
        return now;
    };
    let elapsed_ms = chrono::Utc::now()
        .timestamp_millis()
        .saturating_sub(start_ms);
    if elapsed_ms <= 0 {
        return now;
    }
    now.checked_sub(std::time::Duration::from_millis(elapsed_ms as u64))
        .unwrap_or(now)
}

/// Close out a wake turn — the only flush site for its in-flight streamed
/// entries (wake turns skip `PromptResponse`). Markers: visible output closes
/// with one; silence closes with none — except failures, which surface even
/// when silent (the user's standing instruction stopped executing invisibly).
/// Silent rate limits defer to the retry notifications, like the real-turn
/// rails. A hook-denied wake follows the cancelled policy (no failure
/// carve-out): the `HookAnnotation` warning attributes the deny but is not
/// turn output, so a silent block closes without a marker.
///
/// `cancel_trigger` is the signal's `_meta.cancelTrigger`. `"send_now"` marks
/// an internal cancel-and-send, so the `TurnCancelled` marker is suppressed
/// (wire trigger wins; `expect_send_now_cancel` is the older-shell fallback).
/// `cancellation_category` is the signal's `_meta.cancellationCategory`;
/// `"HookDenied"` picks the blocked-by-a-hook marker.
pub(super) fn finish_wake_turn(
    agent: &mut AgentView,
    prompt_id: &str,
    stop_reason: &str,
    agent_result: Option<&str>,
    cancel_trigger: Option<&str>,
    cancellation_category: Option<&str>,
) {
    use crate::scrollback::blocks::SessionEvent;

    let had_output = agent.session.tracker.output_since_last_finish();
    agent.session.tracker.finish_turn(&mut agent.scrollback);
    // The stored `turn_start_ms` may belong to an earlier turn (a silent wake
    // streamed no deltas of its own; interleaved deltas can re-stamp it) —
    // claim an elapsed only when the anchor is provably this wake's.
    let anchor_is_ours = agent.turn_start_ms_prompt.as_deref() == Some(prompt_id);
    let elapsed = if had_output && anchor_is_ours {
        agent.turn_start_ms.and_then(|start_ms| {
            let ms = chrono::Utc::now()
                .timestamp_millis()
                .saturating_sub(start_ms);
            (ms >= 0).then(|| std::time::Duration::from_millis(ms as u64))
        })
    } else {
        None
    };
    // Wire trigger carries this case; pid-matched fallback is consistency-only (do not take/clear).
    let send_now_cancel = match cancel_trigger {
        Some(trigger) => trigger == "send_now",
        None => agent.expect_send_now_cancel.as_deref() == Some(prompt_id),
    };
    let already_failed = agent.failed_wake_marker_for.as_deref() == Some(prompt_id);
    let event = match stop_reason {
        "error" | "rate_limit"
            if already_failed || (stop_reason == "rate_limit" && !had_output) =>
        {
            None
        }
        "error" | "rate_limit" => {
            agent.failed_wake_marker_for = Some(prompt_id.to_string());
            // A dedicated banner (re-auth, overflow, disk-full, formatted
            // request failure) from the retry-state rail already covers this
            // failure — same dedupe as `turn_failed_event` on the local rails.
            if crate::app::dispatch::scrollback_has_recent_error_banner(&agent.scrollback) {
                None
            } else {
                let error = if stop_reason == "error" {
                    crate::app::error_display::format_request_failure(
                        None,
                        None,
                        agent_result.unwrap_or("unknown error"),
                    )
                    .message()
                } else {
                    agent_result
                        .map(str::to_string)
                        .unwrap_or_else(|| "rate limited".to_string())
                };
                Some(SessionEvent::TurnFailed { error, elapsed })
            }
        }
        "cancelled" if !had_output => None,
        // Send-now cancel: no marker (the sender's new prompt is the next turn).
        "cancelled" if send_now_cancel => None,
        "cancelled" => Some(crate::app::turn_completion::cancelled_turn_event(
            cancellation_category,
            elapsed.unwrap_or_default(),
        )),
        _ if !had_output => None,
        _ => Some(SessionEvent::TurnCompleted { elapsed }),
    };
    if event.is_some() {
        crate::app::turn_completion::push_turn_terminal_marker(agent, event, Some(prompt_id));
    }
}
